@Component("control-handler")
@ProcessingGroup("control-processing-group")
public class ControlEventHandler {
	
	// core constructor
	ControlEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateControlEvent
     */
    @EventHandler
    public void handle( CreateControlEvent event) {
        entityManager.persist(new Control(event.getControlId(), event.getName(), event.getObjective(), event.getOwnerDepartment(), event.getPolicy(), event.getControlTests(), event.getEvidence(), event.getRisks(), event.getObligations(), event.getProcedures(), event.getIssues(), event.getControlType(), event.getFrequency(), event.getStatus()));
    }

    /*
     * @param	event UpdateControlEvent
     */
    @EventHandler
    public Control handle( UpdateControlEvent event) {
    	entityManager.merge(new Control(event.getControlId(), event.getName(), event.getObjective(), event.getOwnerDepartment(), event.getPolicy(), event.getControlTests(), event.getEvidence(), event.getRisks(), event.getObligations(), event.getProcedures(), event.getIssues(), event.getControlType(), event.getFrequency(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteControlEvent
     */
    @EventHandler
    public void on( DeleteControlEvent event) {
    	Control entity = new Control();
   
    	// ------------------------------------------
    	// apply the ControlId
    	// ------------------------------------------
    	entity.setControlId( event.getControlId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ControlRepository controlEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ControlEventHandler.class.getName());

}
